<script setup lang="ts">
type Part = { text: string; syllables?: number }
type Line = { id: number; parts: Part[]; gap: boolean; stanzaBreak: boolean }
type RhymeFeedback = { a: string; b: string; rhymes: boolean }
type SavedText = { id: string; title: string; text: string; language: string; sourceUrl?: string; period?: string; year?: string; updatedAt: number }
type PairRecord = { a: string; b: string; frequency: number; sections: number[]; confidence: number; status: string }
type VowelRecord = { a: string; b: string; count: number; examples: string[] }
const languages = [{ value:'en',label:'English'},{value:'fr',label:'French'},{value:'es',label:'Spanish'},{value:'it',label:'Italian'},{value:'enm',label:'Middle English'},{value:'fro',label:'Old French'},{value:'ang',label:'Anglo-Norman'},{value:'other',label:'Other / uncertain'}]
const colors = ['#dff1e5','#fce4d8','#e5e8fb','#f8edc8','#f4dff0','#d9eff1','#eee2d5','#e4e9df']
const starterPairs = [['pounde','grounde'],['begynne','thinne'],['be','yemanry'],['stryfe','lyfe'],['me','be'],['disgrate','state'],['ende','amende'],['rychesse','kyndnesse'],['ayre','fayre'],['bolde','solde'],['the','see'],['tresouré','be'],['the','poverté'],['none','Johnn'],['rowe','sawe'],['Calveré','be'],['day','Abbey'],['contré','me'],['ryvere','bryre']]
const language=ref('enm'), poemTitle=ref(''), poemInput=ref(''), sourceUrl=ref(''), period=ref(''), year=ref(''), stanzaLength=ref(4)
const lines=ref<Line[]>([]), nextId=ref(1), fileInput=ref<HTMLInputElement|null>(null), feedbackFile=ref<HTMLInputElement|null>(null)
const feedback=ref<RhymeFeedback[]>([]), savedTexts=ref<SavedText[]>([]), selectedSavedId=ref(''), status=ref(''), storageReady=ref(false)
const editingWord=ref<{lineId:number;partIndex:number}|null>(null), activeRhymeId=ref<number|null>(null)
const hasPoem=computed(()=>lines.value.length>0)
function normalize(word:string){return word.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’'-]/g,'')}
function tokenize(text:string):Part[]{const tokens=text.match(/[\p{L}\p{M}]+(?:[’'-][\p{L}\p{M}]+)*|[^\p{L}\p{M}]+/gu)??[];return tokens.map(text=>/[\p{L}\p{M}]/u.test(text)?{text,syllables:countWordSyllables(text,language.value)}:{text})}
function wordParts(line:Line){return line.parts.map((part,partIndex)=>({part,partIndex})).filter(x=>x.part.syllables!==undefined)}
function lineText(line:Line){return line.parts.map(p=>p.text).join('')}
function lineTotal(line:Line){return wordParts(line).reduce((sum,x)=>sum+(x.part.syllables??0),0)}
function isTruncated(line:Line){return /(?:\.{3,}|…+)\s*$/.test(lineText(line))}
function finalWord(line:Line){return isTruncated(line)?'':wordParts(line).at(-1)?.part.text??''}
function pairKey(a:string,b:string){return[normalize(a),normalize(b)].sort().join('|')}
function rhymeTail(word:string){let value=normalize(word).replace(/y$/g,'i');if(!value)return '';const accented=/[éèê]$/i.test(word);if(!accented&&value.length>2&&value.endsWith('e')&&!/[aeiouy]e$/.test(value)&&/[aeiou]/.test(value.slice(0,-1)))value=value.slice(0,-1);return(value.match(/[aeiou]+[^aeiou]*$/i)?.[0]??value).replace(/([aeiou])\1+$/g,'$1')}
function savedJudgment(a:string,b:string){return feedback.value.find(x=>pairKey(x.a,x.b)===pairKey(a,b))}
function probability(a:string,b:string){const judgment=savedJudgment(a,b);if(judgment?.rhymes===true)return 100;if(judgment?.rhymes===false)return 0;return rhymeTail(a)&&rhymeTail(a)===rhymeTail(b)?82:18}
function rhymeReasons(a:string,b:string){const x=normalize(a),y=normalize(b),result:string[]=[];if(/[éèê]$/i.test(a)||/[éèê]$/i.test(b))result.push('Treats final accented é/è/ê as pronounced.');if(x.endsWith('e')!==y.endsWith('e'))result.push('Assumes written final -e may be silent.');if(rhymeTail(a)&&rhymeTail(a)===rhymeTail(b))result.push(`Matching spelling-based rhyme tail: ${rhymeTail(a)}.`);if(!result.length)result.push('No exact spelling-tail match; historical sound may still rhyme. Judge this pairing manually.');return result}
function countWordSyllables(word:string,lang:string){const accented=/[éèê]$/i.test(word),normalized=word.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let count=0,inVowel=false;for(const c of normalized){const vowel=/[aeiouy]/i.test(c);if(vowel&&!inVowel)count++;inVowel=vowel}if(['fr','fro','ang'].includes(lang)){if(count>1&&/e$/.test(normalized)&&!accented)count--}else if(['en','enm'].includes(lang)){if(count>1&&/e$/.test(normalized)&&!accented&&!/(le|ye)$/.test(normalized))count--;if(/[^aeiou]le$/.test(normalized))count++}return Math.max(1,count)}
function analyze(){let stanzaBreak=false;const result:Line[]=[];for(const raw of poemInput.value.split(/\r?\n/)){if(!raw.trim()){if(result.length)stanzaBreak=true;continue}result.push({id:nextId.value++,parts:tokenize(raw.trim()),gap:false,stanzaBreak});stanzaBreak=false}lines.value=result;editingWord.value=null;activeRhymeId.value=null}
function editSyllables(part:Part,value:string){part.syllables=Math.max(0,Math.min(20,Number(value)||0))}
const sectionIds=computed(()=>{const explicit=lines.value.some((line,i)=>i>0&&line.stanzaBreak);if(explicit)return lines.value.map((_,i)=>lines.value.slice(0,i+1).filter((line,j)=>j>0&&line.stanzaBreak).length);return lines.value.map((_,i)=>Math.floor(i/Math.max(2,Math.min(20,Number(stanzaLength.value)||4))))})
const sections=computed(()=>[...new Set(sectionIds.value)].map(id=>({id,indices:lines.value.map((_,i)=>i).filter(i=>sectionIds.value[i]===id&&!lines.value[i].gap)})))
function endingIndices(sectionId:number){return lines.value.map((line,i)=>({line,i})).filter(x=>sectionIds.value[x.i]===sectionId&&!x.line.gap&&!!finalWord(x.line)).map(x=>x.i)}
const rhymeGroups=computed(()=>{const parent=lines.value.map((_,i)=>i);const find=(x:number):number=>parent[x]===x?x:(parent[x]=find(parent[x]));const join=(a:number,b:number)=>{parent[find(a)]=find(b)};for(let i=0;i<lines.value.length;i++)for(let j=i+1;j<lines.value.length;j++){const a=finalWord(lines.value[i]),b=finalWord(lines.value[j]);if(!a||!b)continue;const judgement=savedJudgment(a,b);if(judgement?.rhymes===true||(judgement?.rhymes!==false&&rhymeTail(a)===rhymeTail(b)))join(i,j)}const compact=new Map<number,number>();return lines.value.map((line,i)=>{if(line.gap||!finalWord(line))return null;const root=find(i);if(!compact.has(root))compact.set(root,compact.size);return compact.get(root)!})})
const schemePatterns=computed(()=>sections.value.map(section=>{const labels=new Map<number,string>();const pattern=section.indices.map(i=>{const group=rhymeGroups.value[i];if(group===null||group===undefined)return'-';if(!labels.has(group))labels.set(group,String.fromCharCode(65+labels.size%26));return labels.get(group)!}).join('');return{...section,pattern}}))
const schemeSummary=computed(()=>{const valid=schemePatterns.value.filter(s=>s.pattern.length>1&&s.pattern.includes('A'));if(!valid.length)return null;const counts=new Map<string,number>();valid.forEach(s=>counts.set(s.pattern,(counts.get(s.pattern)||0)+1));const [pattern,count]=[...counts].sort((a,b)=>b[1]-a[1])[0];return{pattern,count,total:valid.length}})
function rhymeColor(index:number){const group=rhymeGroups.value[index];if(group===null||group===undefined)return'transparent';const count=rhymeGroups.value.filter(x=>x===group).length;return count>1?colors[group%colors.length]:'transparent'}
const pairDictionary=computed<PairRecord[]>(()=>{const observed=new Map<string,{a:string;b:string;frequency:number;sections:Set<number>;confidence:number;status:string}>();for(const section of sections.value){const indices=endingIndices(section.id);for(let x=0;x<indices.length;x++)for(let y=x+1;y<indices.length;y++){const i=indices[x],j=indices[y],a=finalWord(lines.value[i]),b=finalWord(lines.value[j]),judgment=savedJudgment(a,b),sameGroup=rhymeGroups.value[i]===rhymeGroups.value[j];if(!sameGroup&&judgment?.rhymes!==true)continue;const key=pairKey(a,b);const old=observed.get(key);if(old){old.frequency++;old.sections.add(section.id);old.confidence=Math.max(old.confidence,probability(a,b));if(judgment)old.status=judgment.rhymes?'Manually marked rhyme':'Manually marked not rhyme'}else observed.set(key,{a,b,frequency:1,sections:new Set([section.id]),confidence:probability(a,b),status:judgment?(judgment.rhymes?'Manually marked rhyme':'Manually marked not rhyme'):'Spelling-tail / inferred group'})}}
  // Complete each observed rhyme family combinatorially, so A/B and A/C imply B/C.
  const wordsByGroup=new Map<number,Set<string>>();lines.value.forEach((line,i)=>{const word=finalWord(line),group=rhymeGroups.value[i];if(word&&group!==null&&group!==undefined){if(!wordsByGroup.has(group))wordsByGroup.set(group,new Set());wordsByGroup.get(group)!.add(word)}})
  for(const [group,wordSet] of wordsByGroup){const words=[...wordSet];if(words.length<3)continue;for(let x=0;x<words.length;x++)for(let y=x+1;y<words.length;y++){const a=words[x],b=words[y],key=pairKey(a,b);if(savedJudgment(a,b)?.rhymes===false||observed.has(key))continue;observed.set(key,{a,b,frequency:0,sections:new Set(),confidence:probability(a,b),status:'Inferred from shared rhyme family'})}}
  return[...observed.values()].map(item=>({...item,sections:[...item.sections].sort((a,b)=>a-b)})).sort((a,b)=>b.frequency-a.frequency||a.a.localeCompare(b.a)||a.b.localeCompare(b.b))})
function vowelNucleus(word:string){const normalized=word.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');return normalized.match(/[aeiouy]+/g)?.at(-1)?.toUpperCase()||''}
const vowelCorrespondences=computed<VowelRecord[]>(()=>{const counts=new Map<string,{a:string;b:string;count:number;examples:Set<string>}>();for(const section of sections.value){const indices=endingIndices(section.id);for(let x=0;x<indices.length;x++)for(let y=x+1;y<indices.length;y++){const i=indices[x],j=indices[y],a=finalWord(lines.value[i]),b=finalWord(lines.value[j]);if(!a||!b||rhymeGroups.value[i]!==rhymeGroups.value[j])continue;const va=vowelNucleus(a),vb=vowelNucleus(b);if(!va||!vb||va===vb)continue;const [left,right]=[va,vb].sort();const key=`${left}|${right}`;if(!counts.has(key))counts.set(key,{a:left,b:right,count:0,examples:new Set()});const item=counts.get(key)!;item.count++;item.examples.add(`${a} / ${b}`)}}return[...counts.values()].map(x=>({...x,examples:[...x.examples].slice(0,5)})).sort((a,b)=>b.count-a.count)})
const candidates=computed(()=>lines.value.map((line,i)=>{const word=finalWord(line);if(!word||line.gap)return[];return endingIndices(sectionIds.value[i]).filter(j=>j!==i).map(j=>{const other=finalWord(lines.value[j]),saved=savedJudgment(word,other);return{index:j,word:other,probability:probability(word,other),reasons:rhymeReasons(word,other),accepted:saved?.rhymes===true,judgment:saved?.rhymes}}).sort((a,b)=>b.probability-a.probability)}))
function saveJudgment(i:number,j:number,rhymes:boolean){const a=finalWord(lines.value[i]),b=finalWord(lines.value[j]);if(!a||!b)return;const key=pairKey(a,b);feedback.value=[...feedback.value.filter(x=>pairKey(x.a,x.b)!==key),{a,b,rhymes}]}
function saveText(){const text=hasPoem.value?lines.value.map(lineText).join('\n'):poemInput.value;if(!text.trim()){status.value='Enter text before saving.';return}if(sourceUrl.value.trim()){try{const u=new URL(sourceUrl.value);if(!['http:','https:'].includes(u.protocol))throw 0}catch{status.value='Use a valid http or https source URL, or leave it blank.';return}}const old=savedTexts.value.find(x=>x.id===selectedSavedId.value);const item:SavedText={id:old?.id??`${Date.now()}-${Math.random().toString(36).slice(2)}`,title:poemTitle.value.trim()||'Untitled poem',text,language:language.value,sourceUrl:sourceUrl.value.trim(),period:period.value.trim(),year:year.value.trim(),updatedAt:Date.now()};savedTexts.value=[item,...savedTexts.value.filter(x=>x.id!==item.id)];selectedSavedId.value=item.id;status.value='Saved in this browser.'}
function loadText(item:SavedText){poemTitle.value=item.title;poemInput.value=item.text;language.value=item.language||'enm';sourceUrl.value=item.sourceUrl||'';period.value=item.period||'';year.value=item.year||'';selectedSavedId.value=item.id;analyze();status.value=`Loaded “${item.title}”.`}
function deleteText(id:string){savedTexts.value=savedTexts.value.filter(x=>x.id!==id);if(selectedSavedId.value===id)selectedSavedId.value=''}
onMounted(()=>{try{feedback.value=JSON.parse(localStorage.getItem('verse-rhyme-feedback')||JSON.stringify(starterPairs.map(([a,b])=>({a,b,rhymes:true}))));savedTexts.value=JSON.parse(localStorage.getItem('verse-saved-texts')||'[]')}catch{feedback.value=starterPairs.map(([a,b])=>({a,b,rhymes:true}));savedTexts.value=[]}storageReady.value=true})
watch(feedback,v=>{if(storageReady.value)try{localStorage.setItem('verse-rhyme-feedback',JSON.stringify(v))}catch{/* storage unavailable */}},{deep:true})
watch(savedTexts,v=>{if(storageReady.value)try{localStorage.setItem('verse-saved-texts',JSON.stringify(v))}catch{status.value='Browser storage is unavailable; text could not be saved.'}},{deep:true})
function onFileChange(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{poemInput.value=String(reader.result??'');if(!poemTitle.value)poemTitle.value=file.name.replace(/\.[^.]+$/,'')};reader.readAsText(file);input.value=''}
function importFeedback(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result)) as RhymeFeedback[];if(!Array.isArray(data)||data.some(x=>typeof x.a!=='string'||typeof x.b!=='string'||typeof x.rhymes!=='boolean'))throw 0;feedback.value=[...feedback.value.filter(x=>!data.some(y=>pairKey(x.a,x.b)===pairKey(y.a,y.b))),...data]}catch{window.alert('Please select a valid rhyme-feedback JSON file.')}};reader.readAsText(file);input.value=''}
function exportFeedback(){download(new Blob([JSON.stringify(feedback.value,null,2)],{type:'application/json'}),'verse-rhyme-feedback.json')}
function addMissingLine(index=lines.value.length-1){lines.value.splice(index+1,0,{id:nextId.value++,parts:[],gap:true,stanzaBreak:false})}
function escapeHtml(text:string){return text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!))}
function safeName(){return(poemTitle.value.trim()||'poem').replace(/[^\p{L}\p{N}-]+/gu,'-').replace(/^-|-$/g,'').toLowerCase()||'poem'}
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportHtml(){const title=escapeHtml(poemTitle.value||'Untitled poem'),body=lines.value.map((line,index)=>line.gap?'<p class="line missing">[Missing line]</p>':`<p class="line">${escapeHtml(lineText(line))} <mark style="background:${rhymeColor(index)}">${escapeHtml(finalWord(line))}</mark> <span class="count">(${lineTotal(line)})</span>${isTruncated(line)?' <span>[text incomplete]</span>':''}</p>`).join('\n');download(new Blob([`<!doctype html><html lang="en"><meta charset="utf-8"><title>${title}</title><style>body{font:20px/1.65 Georgia,serif;max-width:760px;margin:48px auto;padding:0 24px}.line{margin:0 0 .18rem}.count{font:14px system-ui;color:#777}mark{color:inherit;border-radius:4px;padding:0 3px}</style><h1>${title}</h1>${body}</html>`],{type:'text/html;charset=utf-8'}),`${safeName()}.html`)}
function exportPdf(){window.print()}
</script>

<template>
  <div class="min-h-screen bg-[#f7f7f4] text-stone-900">
    <header class="border-b border-stone-200 bg-white"><div class="mx-auto flex max-w-5xl items-center justify-between px-5 py-4 sm:px-8"><a href="#top" class="flex items-center gap-3 no-underline"><span class="grid h-9 w-9 place-items-center rounded-lg bg-[#274f3b] text-lg text-white">¶</span><span class="font-semibold">Verse</span></a><nav class="flex items-center gap-4 text-sm"><a href="./rhyme-dictionaries.html" class="font-medium text-[#315d45] underline">Rhyme dictionaries</a><span class="text-stone-500">Poetry analysis</span></nav></div></header>
    <main id="top" class="mx-auto max-w-5xl px-5 py-8 sm:px-8 sm:py-12">
      <section v-if="!hasPoem" class="mx-auto max-w-3xl"><p class="mb-2 text-xs font-semibold uppercase tracking-[.18em] text-[#52715d]">Read closely</p><h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">See the shape of a poem.</h1><p class="mt-3 text-stone-600">Read, compare likely rhymes, and edit syllables only when you need to.</p>
        <div class="mt-7 rounded-2xl border border-stone-200 bg-white p-5 shadow-sm sm:p-7"><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium">Title <input v-model="poemTitle" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2.5" placeholder="Poem title"></label><label class="text-sm font-medium">Language<select v-model="language" class="mt-1.5 block w-full rounded-lg border border-stone-200 bg-white px-3 py-2.5"><option v-for="item in languages" :key="item.value" :value="item.value">{{item.label}}</option></select></label><label class="text-sm font-medium sm:col-span-2">Source URL <input v-model="sourceUrl" type="url" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2.5" placeholder="https://… (optional)"></label><label class="text-sm font-medium">Century / period <input v-model="period" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2.5" placeholder="e.g. 14th century"></label><label class="text-sm font-medium">Year <input v-model="year" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2.5" placeholder="e.g. c. 1380"></label></div><div class="my-4 flex justify-end"><button class="text-sm font-medium text-[#315d45] hover:underline" @click="fileInput?.click()">Upload .txt</button><input ref="fileInput" class="hidden" type="file" accept=".txt,text/plain" @change="onFileChange"></div><label for="poem-text" class="mb-2 block text-sm font-medium">Poem text</label><textarea id="poem-text" v-model="poemInput" rows="12" class="w-full resize-y rounded-lg border border-stone-200 px-3 py-3 font-serif leading-7" placeholder="One verse line per row; blank lines mark stanzas."></textarea><p class="mt-2 text-xs leading-5 text-amber-800">A line ending in … or three or more periods (... / ....) is marked incomplete and excluded from rhyme analysis.</p><div class="mt-5 flex flex-wrap items-end justify-between gap-4"><button class="rounded-lg border border-stone-300 bg-white px-4 py-3 text-sm font-semibold" @click="saveText">Save text</button><button :disabled="!poemInput.trim()" class="rounded-lg bg-[#274f3b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40" @click="analyze">Analyze poem →</button></div><p v-if="status" class="mt-3 text-sm text-[#315d45]" role="status">{{status}}</p></div>
        <section v-if="savedTexts.length" class="mt-5 rounded-2xl border border-stone-200 bg-white p-5"><h2 class="font-semibold">Saved texts <span class="text-sm font-normal text-stone-500">(this browser)</span></h2><ul class="mt-3 space-y-2"><li v-for="item in savedTexts" :key="item.id" class="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-stone-50 px-3 py-2"><button class="text-left text-sm font-medium text-[#315d45] hover:underline" @click="loadText(item)">{{item.title}} <span class="font-normal text-stone-500">· {{item.language}} · {{item.period||'period unspecified'}} {{item.year}}</span></button><button class="text-xs text-stone-500 hover:text-red-700" @click="deleteText(item.id)">Delete</button></li></ul></section><p class="mt-4 text-xs leading-5 text-stone-500">Saved poems remain in this browser. Use <a class="text-[#315d45] underline" href="./rhyme-dictionaries.html">Rhyme dictionaries</a> to build and compare per-text rhyme-pair lists.</p></section>
      <section v-else><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><button class="mb-1 text-sm font-medium text-[#315d45] hover:underline" @click="lines=[];poemInput=''">← New poem</button><h1 class="text-2xl font-semibold">{{poemTitle||'Untitled poem'}}</h1><p class="mt-1 text-xs text-stone-500">{{languages.find(x=>x.value===language)?.label}} · {{period||'period unspecified'}} {{year}} <a v-if="sourceUrl" :href="sourceUrl" target="_blank" rel="noopener" class="underline">Source</a></p></div><div class="flex flex-wrap gap-2"><button class="rounded-lg border border-stone-300 bg-white px-3 py-2 text-sm" @click="saveText">Save text</button><button class="rounded-lg border border-stone-300 bg-white px-3 py-2 text-sm" @click="exportHtml">Download HTML</button><button class="rounded-lg bg-[#274f3b] px-3 py-2 text-sm font-semibold text-white" @click="exportPdf">Save PDF</button></div></div>
        <div class="rounded-2xl border border-stone-200 bg-white shadow-sm"><div class="border-b border-stone-200 px-5 py-4 sm:px-8"><h2 class="font-semibold">Poem</h2><p class="mt-1 text-sm text-stone-500">Line syllable totals remain visible. Click a word to adjust its own count. Blank lines define stanzas; otherwise choose a section length.</p><p v-if="schemeSummary" class="mt-2 text-sm text-[#315d45]">Observed rhyme scheme: <strong>{{schemeSummary.pattern}}</strong><span class="text-stone-500"> · {{schemeSummary.count}} of {{schemeSummary.total}} sections. Schemes are inferred from rhyme groups and can be corrected with pair judgments below.</span></p><label v-if="!lines.some(l=>l.stanzaBreak)" class="mt-2 inline-flex items-center gap-2 text-xs text-stone-600">Section length<select v-model.number="stanzaLength" class="rounded border border-stone-300 bg-white px-2 py-1"><option v-for="n in [4,5,6,7,8,10,12]" :key="n" :value="n">{{n}} lines</option></select></label><p v-if="status" class="mt-2 text-sm text-[#315d45]" role="status">{{status}}</p></div>
          <div class="px-5 py-4 sm:px-8 sm:py-5"><div v-for="(line,index) in lines" :key="line.id" class="poem-row" :class="line.stanzaBreak?'stanza-break':''"><p v-if="line.gap" class="my-2 rounded-lg bg-amber-50 px-3 py-2 text-sm text-amber-900">Missing line — position preserved</p><template v-else><p class="poem-line"><template v-for="(part,partIndex) in line.parts" :key="partIndex"><button v-if="part.syllables!==undefined" class="word-button" :class="partIndex===wordParts(line).at(-1)?.partIndex?'end-word':''" :style="partIndex===wordParts(line).at(-1)?.partIndex&&!isTruncated(line)?{backgroundColor:rhymeColor(index)}:{}" :aria-expanded="editingWord?.lineId===line.id&&editingWord.partIndex===partIndex" :title="`Click to edit syllables for ${part.text}`" @click="editingWord=editingWord?.lineId===line.id&&editingWord.partIndex===partIndex?null:{lineId:line.id,partIndex}">{{part.text}}</button><span v-else>{{part.text}}</span></template><span class="line-total">({{lineTotal(line)}})</span><span v-if="isTruncated(line)" class="truncated-tag">Incomplete ending — excluded from rhyme analysis</span><button v-else class="rhyme-link" :aria-expanded="activeRhymeId===line.id" @click="activeRhymeId=activeRhymeId===line.id?null:line.id">Pairings</button></p>
            <div v-if="editingWord?.lineId===line.id" class="inline-panel"><label class="text-sm text-stone-700">Syllables in “{{line.parts[editingWord.partIndex].text}}” <input :value="line.parts[editingWord.partIndex].syllables" type="number" min="0" max="20" class="ml-2 w-16 rounded border border-stone-300 px-2 py-1 text-center" @input="editSyllables(line.parts[editingWord.partIndex],($event.target as HTMLInputElement).value)"></label><button class="ml-2 text-sm text-stone-500 underline" @click="editingWord=null">Done</button><p class="mt-1 text-xs text-stone-500">Line total: {{lineTotal(line)}} syllables</p></div>
            <div v-if="activeRhymeId===line.id" class="inline-panel rhyme-panel"><div class="mb-2 flex items-center justify-between"><p class="text-sm font-semibold">All pairings in this stanza for {{finalWord(line)}}</p><button class="text-xs text-stone-500 underline" @click="activeRhymeId=null">Close</button></div><p class="mb-3 text-xs leading-5 text-stone-500">The spelling estimate is only a suggestion. Use the controls to mark pairings; your decisions update the poem’s rhyme colors, pattern, and collection.</p><div v-if="candidates[index]?.length" class="space-y-2"><div v-for="candidate in candidates[index]" :key="candidate.index" class="rounded-lg border border-stone-200 p-3"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-serif text-lg">{{candidate.word}} <span class="font-sans text-xs text-stone-500">{{candidate.probability}}% spelling estimate</span><span v-if="candidate.judgment===true" class="ml-2 font-sans text-xs text-green-700">Marked rhyme</span><span v-else-if="candidate.judgment===false" class="ml-2 font-sans text-xs text-amber-700">Marked not rhyme</span></p><p v-for="reason in candidate.reasons" :key="reason" class="mt-1 text-xs leading-5 text-stone-600">{{reason}}</p></div><div class="flex gap-2"><button class="rounded bg-green-50 px-2.5 py-1.5 text-xs font-semibold text-green-800" @click="saveJudgment(index,candidate.index,true)">Mark rhyme</button><button class="rounded bg-stone-100 px-2.5 py-1.5 text-xs font-semibold text-stone-700" @click="saveJudgment(index,candidate.index,false)">Not a rhyme</button></div></div></div></div><p v-else class="text-sm text-stone-500">No other line endings in this stanza.</p></div></template></div><button class="mt-3 text-sm font-medium text-[#315d45] hover:underline" @click="addMissingLine()">+ Add missing line</button></div></div>
        <section class="mt-5 rounded-2xl border border-stone-200 bg-white p-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-lg font-semibold">Rhyme-pair collection for this text</h2><p class="mt-1 text-sm text-stone-600">Pairs are grouped transitively: if “be” rhymes with “me” and “countré,” the collection includes “me / countré.” Frequency counts how often a pair of line endings occurs within one section.</p></div><span class="rounded-full bg-stone-100 px-3 py-1 text-sm">{{pairDictionary.length}} pairs</span></div><div v-if="pairDictionary.length" class="mt-4 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b text-xs uppercase tracking-wide text-stone-500"><th class="px-2 py-2">Word 1</th><th class="px-2 py-2">Word 2</th><th class="px-2 py-2">Frequency</th><th class="px-2 py-2">Sections</th><th class="px-2 py-2">Evidence</th></tr></thead><tbody><tr v-for="pair in pairDictionary" :key="pairKey(pair.a,pair.b)" class="border-b border-stone-100"><td class="px-2 py-2 font-serif text-base">{{pair.a}}</td><td class="px-2 py-2 font-serif text-base">{{pair.b}}</td><td class="px-2 py-2">{{pair.frequency}}</td><td class="px-2 py-2">{{pair.sections.length?pair.sections.map(x=>x+1).join(', '):'family inference'}}</td><td class="px-2 py-2 text-xs text-stone-600">{{pair.status}} · {{pair.confidence}}% spelling estimate</td></tr></tbody></table></div><p v-else class="mt-3 text-sm text-stone-500">No rhyme families yet. Use Pairings beside line endings and mark pairs manually; matching endings will be collected here.</p>
          <div class="mt-6 border-t border-stone-100 pt-4"><h3 class="font-semibold">Vowel and diphthong correspondences</h3><p class="mt-1 text-sm text-stone-600">Exploratory: shows different written vowel nuclei among endings assigned to the same rhyme group. Counts are observed line-ending pair instances, not proof of pronunciation.</p><div v-if="vowelCorrespondences.length" class="mt-3 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b text-xs uppercase tracking-wide text-stone-500"><th class="px-2 py-2">Spellings that co-rhyme</th><th class="px-2 py-2">Observed instances</th><th class="px-2 py-2">Examples</th></tr></thead><tbody><tr v-for="item in vowelCorrespondences" :key="item.a+'|'+item.b" class="border-b border-stone-100"><td class="px-2 py-2 font-semibold">{{item.a}} / {{item.b}}</td><td class="px-2 py-2">{{item.count}}</td><td class="px-2 py-2">{{item.examples.join('; ')}}</td></tr></tbody></table></div><p v-else class="mt-3 text-sm text-stone-500">No different vowel nuclei have been assigned to the same rhyme group yet. Manually mark an uncertain pairing as a rhyme to add it as evidence.</p></div></section>
        <details class="mt-4 rounded-xl border border-stone-200 bg-white p-4"><summary class="cursor-pointer text-sm font-medium">Rhyme feedback</summary><p class="mt-2 text-xs leading-5 text-stone-500">Manual pair judgments are saved in this browser and reused in rhyme analysis.</p><div class="mt-3 flex gap-2"><button class="rounded border border-stone-300 px-2.5 py-1.5 text-xs" @click="exportFeedback">Export examples</button><button class="rounded border border-stone-300 px-2.5 py-1.5 text-xs" @click="feedbackFile?.click()">Import examples</button><input ref="feedbackFile" type="file" accept="application/json,.json" class="hidden" @change="importFeedback"></div></details>
      </section>
    </main>
  </div>
</template>

<style>
.poem-row{margin:0 0 .12rem}.poem-line{margin:0;min-height:1.65em;font-family:Georgia,'Times New Roman',serif;font-size:clamp(1.1rem,2.4vw,1.35rem);line-height:1.65}.word-button{border:0;background:transparent;padding:0 1px;color:inherit;font:inherit;font-style:normal;cursor:pointer}.word-button:hover,.word-button:focus-visible{border-radius:3px;outline:2px solid #9aaa9d;outline-offset:1px}.end-word{border-radius:4px;padding:0 3px}.line-total{display:inline-block;white-space:nowrap;margin-left:.3rem;color:#78756e;font:.75rem ui-sans-serif,system-ui,sans-serif;vertical-align:middle}.truncated-tag{display:inline-block;margin-left:.5rem;border-radius:4px;background:#fff7e6;padding:2px 6px;color:#8a5b16;font:.7rem ui-sans-serif,system-ui,sans-serif;vertical-align:middle}.rhyme-link{margin-left:.5rem;border:0;background:transparent;color:#52715d;font:.72rem ui-sans-serif,system-ui,sans-serif;text-decoration:underline;cursor:pointer}.stanza-break{margin-top:1.1rem}.inline-panel{margin:.35rem 0 .7rem .25rem;border-left:2px solid #d6e0d6;padding:.2rem 0 .2rem .8rem}.rhyme-panel{max-width:760px;border-radius:.5rem;background:#fbfcfa;padding:.7rem}
@media print{body{background:white!important;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}header,button,details,.inline-panel{display:none!important}.word-button{display:inline!important;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}main{max-width:none!important;padding:0!important}.poem-line{font-size:13pt}.stanza-break{margin-top:1rem}}
</style>
